import json,subprocess
from shutil import which

def run(cmd):
    try:
        return subprocess.check_output(cmd, shell=True, stderr=subprocess.DEVNULL).decode('utf-8')
    except Exception:
        return ""

data = {}
# Basic system info
try:
    data['uname'] = subprocess.check_output(['uname','-a']).decode('utf-8')
except Exception:
    data['uname'] = ''

# CPU and processor details
data['lscpu'] = run('lscpu')
try:
    data['cpu_count'] = int(subprocess.check_output(['nproc']).decode('utf-8').strip())
except Exception:
    data['cpu_count'] = None

data['cpuinfo'] = run('cat /proc/cpuinfo')

# Block devices
data['lsblk'] = run('lsblk -J')

# Memory
data['free'] = run('free -b')

# lshw if available
if which('lshw'):
    data['lshw'] = run('lshw -json')
else:
    data['lshw'] = ''

# Save JSON
with open('temp_sys_info/sys_meta.json','w') as f:
    json.dump(data, f, indent=2)

# Print cpu count for immediate answer
print(data['cpu_count'] if data['cpu_count'] is not None else '')
